export function renderNginxConf({ repoRoot, instance, devServerPorts, devServerHost, proxyPort }) {
  write(
    join(stateDirFor(instance, repoRoot), 'nginx.conf'),
    nginxConf({ instance, devServerPorts, devServerHost, proxyPort }),
  );
}
=== attachInstance ===
export async function attachInstance({ repoRoot, instance, exec }) {
  const alreadyAttached = await isAttached({ instance, exec });
  if (alreadyAttached) {
    // The routine case for `just up` on an existing worktree: reconcile aliases from a structured
    // membership check, never by calling `docker network connect` and reading its stderr.
    await reconcileAliases({ instance, exec });
  } else {
    const connect = await exec('docker', connectArgs(instance));
    if (connect.code === 0) {
      // Freshly attached with every alias it needs.
    } else {
      if (ALREADY_CONNECTED.test(connect.stderr)) {
        // Race fallback only, not the primary path: something else attached this instance's
        // network in the gap between the `isAttached` check above and this connect call. Docker's
        // stderr text is the sole signal available for that narrow window. Do not let a future
        // edit promote this back to deciding the ordinary already-attached case — that's what
        // `isAttached` is for.
        await reconcileAliases({ instance, exec });
      } else {
        throw new Error(
          `Could not attach ${instance} to the shared proxy: ${connect.stderr || connect.stdout}`,
        );
      }
    }
  }

  // Ahead of the instance conf, every time: the instance conf's `map` blocks and long
  // instance-scoped variable names only parse at all once these buckets are raised, and the very
  // next call validates the whole config.
  const tuning = await exec('docker', [
    'cp',
    join(stateDirFor(instance, repoRoot), 'proxy-tuning.conf'),
    `${PROXY_CONTAINER}:/etc/nginx/conf.d/${PROXY_TUNING_CONF_NAME}`,
  ]);
  if (tuning.code !== 0) {
    throw new Error(
      `Could not install the shared proxy tuning config: ${tuning.stderr || tuning.stdout}`,
    );
  }

  const defaultServer = await exec('docker', [
    'cp',
    join(stateDirFor(instance, repoRoot), 'proxy-default-server.conf'),
    `${PROXY_CONTAINER}:/etc/nginx/conf.d/${NGINX_IMAGE_DEFAULT_CONF_NAME}`,
  ]);
  if (defaultServer.code !== 0) {
    throw new Error(
      `Could not install the shared proxy default server: ${defaultServer.stderr || defaultServer.stdout}`,
    );
  }

  const copy = await exec('docker', [
    'cp',
    join(stateDirFor(instance, repoRoot), 'nginx.conf'),
    `${PROXY_CONTAINER}:/etc/nginx/conf.d/${confName(instance)}`,
  ]);
  if (copy.code !== 0) {
    throw new Error(`Could not install the nginx config for ${instance}: ${copy.stderr || copy.stdout}`);
  } else {
    await reload(exec);
  }
}
